from fastmcp import Server
from typing import Any

def create_proxy_server(backend_server: Server) -> Server:
    """Create a transparent proxy server that forwards all requests to the backend."""
    proxy = Server("proxy")

    # Proxy tools
    if hasattr(backend_server, '_tools'):
        for tool_name, tool_impl in backend_server._tools.items():
            def make_tool_handler(original_tool):
                async def proxy_tool_handler(**kwargs):
                    if hasattr(original_tool, 'func'):
                        result = original_tool.func(**kwargs)
                    else:
                        result = original_tool(**kwargs)
                    return result
                return proxy_tool_handler

            handler = make_tool_handler(tool_impl)
            proxy.add_tool(
                handler,
                name=tool_name,
                description=getattr(tool_impl, 'description', ''),
                inputSchema=getattr(tool_impl, 'inputSchema', {})
            )

    # Proxy resources
    if hasattr(backend_server, '_resources'):
        for resource_uri, resource_impl in backend_server._resources.items():
            def make_resource_handler(original_resource):
                async def proxy_resource_handler(uri: str):
                    if hasattr(original_resource, 'func'):
                        result = original_resource.func(uri)
                    else:
                        result = original_resource(uri)
                    return result
                return proxy_resource_handler

            handler = make_resource_handler(resource_impl)
            proxy.add_resource(
                resource_uri,
                handler,
                description=getattr(resource_impl, 'description', '')
            )

    return proxy

